import { atom, update } from 'claude-code'
import type { Register } from 'claude-code'

import { DEFAULTS } from './defaults.js'
import { BADGE_COLOR_NAMES, BADGE_NAMES, BADGES, badgeColorsCommand, badgesCommand, registerBadges } from './badges.js'
import { ON_OFF, choices, suggest } from './autocomplete.js'

// Generated by scripts/build-plugins.mjs from the shared code in hooks/.
const prefsAtom = atom({ plugin: 'message-badges', key: 'prefs' } as const, DEFAULTS, { shape: 'prefs-1' })

export const register: Register = on => {
  on('prompt.autocomplete', async ($, e, next) => {
    const mine = suggest(e, 'badges', {
    first: [...choices(BADGE_NAMES, n => `${BADGES[n]?.you ?? '◆ You'} · ${BADGES[n]?.claude ?? '✦ Claude'}`), { name: 'colors', description: 'Pick the badge colors' }, ...[{ name: 'list', description: 'Show every option' }, { name: 'off', description: 'Turn off' }]],
    next: { colors: choices(BADGE_COLOR_NAMES) },
  })
    if (mine === undefined) return next(e)
    const theirs = await next(e)
    return { suggestions: [...theirs.suggestions, ...mine] }
  })
  registerBadges(on)
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'badges', description: 'Add badges to messages', argumentHint: '<design> | colors <set> | list | off' })
    const stored = await $.store.get('prefs')
    await update($, prefsAtom, () => ({ ...DEFAULTS, ...(stored !== null && typeof stored === 'object' ? stored : {}) }))
    return next(e)
  })
  on('command.run', { command: 'badges' }, async ($, e) => {
    const words = e.args.trim().split(/\s+/).filter(w => w !== '')
    const first = words[0]?.toLowerCase()
    const rest = words.slice(1).join(' ')
    return { text: await (first === 'colors' ? badgeColorsCommand($, words[1]?.toLowerCase(), '/badges colors') : badgesCommand($, first, '/badges')) }
  })
}
